def paragraph(text='',style=None):
    p=doc.add_paragraph(text,style)
    f=p.paragraph_format;f.alignment=WD_ALIGN_PARAGRAPH.JUSTIFY
    f.first_line_indent=Cm(1.25);f.line_spacing=1.5;f.space_before=Pt(0);f.space_after=Pt(0)
    for r in p.runs:
        r.font.name='Times New Roman';r.font.size=Pt(14);r.font.color.rgb=RGBColor(0,0,0);r.bold=False;r.italic=False
    return p

def heading(text,level=1):
    p=paragraph(text,'Heading '+str(level));p.paragraph_format.keep_with_next=True
    return p

def items(values):
    for x in values:paragraph('— '+x.rstrip(';.')+';')

def table(caption,headers,rows):
    p=paragraph(caption);p.paragraph_format.space_before=Pt(8);p.paragraph_format.space_after=Pt(4);p.paragraph_format.keep_with_next=True
    t=doc.add_table(rows=1,cols=len(headers));t.style='Normal Table'
    # Same monochrome borders and width as the original document.
    props=t._tbl.tblPr
    borders=OxmlElement('w:tblBorders')
    for edge in ['top','left','bottom','right','insideH','insideV']:
        e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4' if edge in ['top','left','bottom','right'] else '2');e.set(qn('w:color'),'000000');borders.append(e)
    props.append(borders)
    width=props.find(qn('w:tblW'));width.set(qn('w:type'),'pct');width.set(qn('w:w'),'5000')
    for c,value in zip(t.rows[0].cells,headers):c.text=value
    for row in rows:
        for c,value in zip(t.add_row().cells,row):c.text=str(value)
    t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
    for row in t.rows:
        row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
        for cell in row.cells:
            for p in cell.paragraphs:
                f=p.paragraph_format;f.first_line_indent=Cm(0);f.line_spacing=1.0;f.space_after=Pt(0)
                for r in p.runs:r.font.name='Times New Roman';r.font.size=Pt(14);r.font.color.rgb=RGBColor(0,0,0);r.bold=False
    paragraph()

def image(name,caption,crop=None,width=16.5):
    source=ROOT/'docs/images'/name
    if crop:
        im=Image.open(source);out=ROOT/'docs/images'/('report-'+name);im.crop(crop).save(out);source=out
    p=paragraph();p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.keep_with_next=True
    p.add_run().add_picture(str(source),width=Cm(width))
    p=paragraph(caption);p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.first_line_indent=Cm(0)

def command(text):
    p=paragraph(text);p.paragraph_format.alignment=WD_ALIGN_PARAGRAPH.LEFT
    for r in p.runs:r.font.name='Consolas';r.font.size=Pt(12)

p=paragraph('СОДЕРЖАНИЕ');p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.space_before=Pt(24);p.paragraph_format.space_after=Pt(18)
for text in ['ВВЕДЕНИЕ','1 ЦЕЛЬ, ЗАДАЧИ И ГРАНИЦЫ ПРОЕКТА','2 ПРОЕКТИРОВАНИЕ МОДУЛЕЙ','3 ТРЕБОВАНИЯ К СИСТЕМЕ','4 МОДЕЛЬ И ХРАНЕНИЕ ДАННЫХ','5 РЕАЛИЗАЦИЯ И ЗАПУСК ПРОЕКТА','6 ПРОВЕРКА РЕАЛИЗОВАННЫХ МОДУЛЕЙ','7 ПЛАН РАЗРАБОТКИ МОДУЛЕЙ 3–5','СПИСОК ИСТОЧНИКОВ']:
    paragraph(text)
